const crypto = require('crypto');
const out = [];

// Pull existing hashes from 'Check Existing Hashes' node
let existingHashes = new Set();
try {
  const existingRecords = $('Check Existing Hashes').all();
  existingHashes = new Set(existingRecords.map(item => item.json?.hash_id).filter(Boolean));
} catch (e) {
  // Safe fallback
}

for (const it of $input.all()) {
  const j = it.json || {};
  let jobs = [];

  if (Array.isArray(j.jobs_results)) jobs = j.jobs_results;
  else if (Array.isArray(j.data)) jobs = j.data;
  else if (Array.isArray(j.results)) jobs = j.results;
  else if (Array.isArray(j.jobs)) jobs = j.jobs;
  else jobs = [j];

  for (const raw of jobs) {
    const company = (raw.company_name || raw.company || raw.employer || '').toString().trim();
    const title = (raw.title || raw.job_title || raw.position || '').toString().trim();
    const location = (raw.location || raw.job_location || raw.city || '').toString().trim();

    const rawUrl = raw.apply_options?.[0]?.link || raw.job_url || raw.url || raw.link || raw.jobUrl || raw.job_id || '';
    const job_url = rawUrl.toString().trim();

    if (!job_url) continue;

    const description = (raw.description || raw.job_description || raw.summary || '').toString();
    const source = (raw.via || raw.source || raw.site || j.source || 'Google Jobs').toString().trim();

    const hash_id = crypto.createHash('md5').update(job_url.toLowerCase()).digest('hex');

    if (!existingHashes.has(hash_id)) {
      out.push({ 
        json: { company, title, location, job_url, description, source, hash_id } 
      });
    }
  }
}

return out;

