// 1. Get the original job details currently being processed in the loop
const originalJob = $('Loop Over Items').item.json;

// 2. Get the AI's scored output
const aiResult = $input.item.json.output || $input.item.json;

// 3. Package reasoning as JSON string for Supabase and email digests
const reasoning = JSON.stringify({
  summary: aiResult.summary || "",
  pros: aiResult.pros || [],
  cons: aiResult.cons || [],
  missing_keywords: aiResult.missing_keywords || []
});

// 4. Merge together
return {
  json: {
    ...originalJob,
    profile_id: $('Webhook').item.json.body?.user_id || 'aridon',
    match_score: aiResult.match_score || 0,
    summary: aiResult.summary || "",
    pros: aiResult.pros || [],
    cons: aiResult.cons || [],
    missing_keywords: aiResult.missing_keywords || [],
    reasoning: reasoning
  }
};

const rows = $input.all().map(i => i.json).filter(j => Object.keys(j).length > 0);
const recipient = $('Webhook').item.json.body?.user_name || 'Candidate';
let html = `<h2>New High-Match Jobs for ${recipient}</h2>`;
for (const j of rows) {
  let r = {};
  try { r = JSON.parse(j.reasoning || '{}'); } catch (e) { r = {}; }
  const pros = (r.pros || []).map(p => '<li>' + p + '</li>').join('');
  const cons = (r.cons || []).map(c => '<li>' + c + '</li>').join('');
  html += '<div style="margin-bottom:16px">';
  html += '<h3>' + j.title + ' — ' + j.company + ' (' + j.match_score + '/100)</h3>';
  html += '<p>' + (j.location || '') + '</p>';
  html += '<p><strong>Pros:</strong></p><ul>' + pros + '</ul>';
  html += '<p><strong>Cons:</strong></p><ul>' + cons + '</ul>';
  html += '<p><a href="' + j.job_url + '">Apply here</a></p>';
  html += '</div><hr>';
}
return [{ json: { html, count: rows.length } }];
